html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #05060a;
}

canvas {
  display: block;
  width: 100vw;
  height: 100vh;
  cursor: crosshair;
}

'use strict';
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const COUNT = 3200, SEPARATION = 320, REPEL = 110, SCALE = 6;

let W, H, dpr;
const pointer = { x: -9e9, y: -9e9 };
const particles = [];

// Pre-rendered glow sprite (much faster than shadowBlur per particle)
const sprite = document.createElement('canvas');
sprite.width = sprite.height = 64;
const sctx = sprite.getContext('2d');
const grad = sctx.createRadialGradient(32, 32, 0, 32, 32, 32);
grad.addColorStop(0, 'rgba(255,255,255,1)');
grad.addColorStop(0.25, 'rgba(140,190,255,0.8)');
grad.addColorStop(1, 'rgba(80,120,255,0)');
sctx.fillStyle = grad;
sctx.fillRect(0, 0, 64, 64);

function targetsFromText(text) {
  const off = document.createElement('canvas');
  off.width = W; off.height = H;
  const octx = off.getContext('2d');
  octx.fillStyle = '#fff';
  octx.textAlign = 'center';
  octx.textBaseline = 'middle';
  let size = 100;
  octx.font = `bold ${size}px sans-serif`;
  while (octx.measureText(text).width < W * 0.86 && size < 300) {
    size += 4;
    octx.font = `bold ${size}px sans-serif`;
  }
  octx.fillText(text, W / 2, H / 2);

  const data = octx.getImageData(0, 0, W, H).data;
  const pts = [];
  for (let y = 0; y < H; y += 4) {
    for (let x = 0; x < W; x += 4) {
      if (data[(y * W + x) * 4 + 3] > 128) pts.push({ x, y });
    }
  }
  return pts;
}

function spawn(pts) {
  particles.length = 0;
  for (let i = 0; i < COUNT; i++) {
    const t = pts[i % pts.length];
    const angle = Math.random() * Math.PI * 2;
    const radius = Math.max(W, H) * (0.4 + Math.random() * 0.5);
    particles.push({
      x: W / 2 + Math.cos(angle) * radius,
      y: H / 2 + Math.sin(angle) * radius,
      vx: 0, vy: 0,
      tx: t.x, ty: t.y,
      ox: t.x, oy: t.y,        // original slot, for re-jittering
      size: 2 + Math.random() * 2.5,
      twinkle: Math.random() * Math.PI * 2,
    });
  }
}

function resize() {
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  spawn(targetsFromText('Hello, world'));
}

window.addEventListener('resize', resize);
window.addEventListener('pointermove', e => { pointer.x = e.clientX; pointer.y = e.clientY; });
window.addEventListener('pointerleave', () => { pointer.x = pointer.y = -9e9; });

let last = performance.now();
function frame(now) {
  const dt = Math.min((now - last) / 16.6, 2);
  last = now;
  ctx.clearRect(0, 0, W, H);

  // trailing fade instead of hard clear
  ctx.globalCompositeOperation = 'source-over';
  ctx.fillStyle = 'rgba(5,6,10,0.35)';
  ctx.fillRect(0, 0, W, H);
  ctx.globalCompositeOperation = 'lighter';

  for (const p of particles) {
    // swirl on the way in: orbit around target while far away
    const dx = p.tx - p.x, dy = p.ty - p.y;
    const dist = Math.hypot(dx, dy) || 1;
    const spiral = Math.min(dist / SEPARATION, 1) * 0.05;
    p.vx += (dx / dist) * 0.12 + (-dy / dist) * spiral * 2;
    p.vy += (dy / dist) * 0.12 + ( dx / dist) * spiral * 2;

    // pointer repulsion
    const px = p.x - pointer.x, py = p.y - pointer.y;
    const pd = Math.hypot(px, py);
    if (pd < REPEL && pd > 0.01) {
      const f = (REPEL - pd) / REPEL * 1.6;
      p.vx += (px / pd) * f;
      p.vy += (py / pd) * f;
    }

    p.vx *= 0.86; p.vy *= 0.86;
    p.x += p.vx * dt; p.y += p.vy * dt;

    // gentle shimmer at rest
    p.twinkle += 0.04 * dt;
    const s = p.size * (2.2 + Math.sin(p.twinkle) * 0.5);
    ctx.globalAlpha = 0.5 + Math.sin(p.twinkle) * 0.15;
    ctx.drawImage(sprite, p.x - s, p.y - s, s * 2, s * 2);
  }
  ctx.globalAlpha = 1;
  requestAnimationFrame(frame);
}

resize();
requestAnimationFrame(frame);

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = process.env.PORT || 3000;
const ROOT = __dirname;
const TYPES = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript' };

http.createServer((req, res) => {
  const file = path.join(ROOT, req.url === '/' ? 'index.html' : path.normalize(req.url));
  if (!file.startsWith(ROOT)) { res.writeHead(403); return res.end(); }
  fs.readFile(file, (err, data) => {
    if (err) { res.writeHead(404); return res.end('Not found'); }
    res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream' });
    res.end(data);
  });
}).listen(PORT, () => console.log(`Serving ${ROOT} on http://localhost:${PORT}`));

